  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Beowulf and the Anglo Saxon Hero$j$, $j${"readings": [{"title": "1 Samuel 17 (King James Version)", "url": "/portal/bible/1Samuel/17"}], "body": "English 4 is a journey through British literature, the writing that shaped the English language and much of the world's literature. We begin with Beowulf, an epic poem composed in Old English, probably between the years 700 and 1000. We do not know who wrote it.\n\nAn epic is a long narrative poem about a hero whose deeds matter to a whole people. Beowulf, a warrior of the Geats, crosses the sea to help the Danish king Hrothgar, whose hall, Heorot, is attacked by the monster Grendel. Beowulf defeats Grendel, then Grendel's mother, and as an old king he faces a dragon in a last battle. Three battles, three monsters: the poem is built on a clear plot.\n\nStudy the features. Alliteration repeats beginning sounds within a line. A caesura is a pause in the middle of a line. A kenning is a compound phrase that names a thing indirectly, such as whale road for the sea. The poem opens with the word Hwaet, which means something like Listen or Lo, a call to attention.\n\nThe Anglo Saxon hero values courage, loyalty and fame, and the poem also shows a sense of fate. Compare that with Scripture. David faced Goliath trusting the LORD, not his own strength, in 1 Samuel 17. A Christian reader notices the difference between boasting in strength and trusting God.\n\nYour task: (1) Summarize the three battles of Beowulf in three sentences. (2) Name and define two features of Old English poetry. (3) Compare the source of strength for Beowulf with the source of strength for David.\n\nFlorida standards: ELA.12.R.1.1, ELA.12.R.1.2, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.1, ELA.12.R.1.2, ELA.K12.EE.1.1", "script": "Welcome to English 4. I am Dr. Alex L. Jenkins Sr., and I am honored to walk with you through the writing of Britain. Listen, this is the last full course of your high school English, and it is a journey through the books that shaped our language, our faith and our world.\n\nWe start at the very beginning, with a poem called Beowulf. It was composed in Old English, probably between the years 700 and 1000, and nobody knows who wrote it. It begins with one word, Hwaet. That means something like Listen, or Lo. Even a thousand years ago, a storyteller knew how to get your attention.\n\nNow watch this. Beowulf is an epic, a long poem about a hero whose deeds matter to a whole people. Beowulf crosses the sea to help King Hrothgar, whose great hall is attacked by a monster named Grendel. He defeats Grendel, then Grendel's mother, and as an old king he faces a dragon. Three battles, three monsters.\n\nLook at the craft. Alliteration repeats beginning sounds. A caesura is a pause in the middle of a line. A kenning is a picture name, like whale road for the sea.\n\nNow compare. Beowulf trusts his strength and wants lasting fame. David faced Goliath in the name of the LORD, saying the battle is the LORD'S. Both are brave, but they trust different things.\n\nYour task is to summarize the three battles, define two features of Old English poetry, and compare the sources of strength. Take the four question check when you finish. Brave hearts need the right foundation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Beowulf and the Anglo Saxon Hero$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Chaucer and the Canterbury Tales$j$, $j${"readings": [{"title": "James 1 (King James Version)", "url": "/portal/bible/James/1"}], "body": "Geoffrey Chaucer lived in the late 1300s and wrote in Middle English, the language of England after the Norman Conquest of 1066. His greatest work, The Canterbury Tales, is a collection of stories told by pilgrims traveling together from the Tabard Inn in Southwark to the shrine of Thomas Becket at Canterbury.\n\nThe Tales use a frame narrative, a story that holds other stories inside it. The General Prologue introduces the pilgrims, including a knight, a miller, a prioress, a merchant and a parson, and each pilgrim tells a tale. The opening lines describe April showers and the longing of people to go on pilgrimage: Whan that Aprill with his shoures soote, the droghte of March hath perced to the roote.\n\nChaucer uses irony and satire gently. He describes a prioress with fine manners but too much interest in fashion, and a pardoner who sells relics for money. Yet he shows real goodness in the parson, who practices what he preaches. That is a point Scripture also makes: in James 1:22, be doers of the word, and not hearers only.\n\nReading Middle English is easier when you read aloud. Many words look strange but sound familiar.\n\nYour task: (1) Explain what a frame narrative is. (2) Name two pilgrims and tell what Chaucer shows about each. (3) Explain how the parson is a model of integrity, and connect that to James 1:22.\n\nFlorida standards: ELA.12.R.1.1, ELA.12.R.1.3, ELA.12.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.1, ELA.12.R.1.3, ELA.12.R.3.1", "script": "Now we travel forward about four hundred years, to the late 1300s, and to a poet named Geoffrey Chaucer. Listen, Chaucer wrote in Middle English, the language of England after the Norman Conquest of 1066. If you read it aloud, you will be surprised how much you understand.\n\nHis masterpiece is The Canterbury Tales. A group of pilgrims travel together from an inn in Southwark to the shrine at Canterbury, and to pass the time, each one tells a story. That is called a frame narrative, a story that holds other stories inside it.\n\nLook at how it begins. Whan that Aprill with his shoures soote, the droghte of March hath perced to the roote. That is April with sweet showers. Chaucer paints a spring morning, and then he introduces the travelers: a knight, a miller, a prioress, a merchant, a parson.\n\nNow watch this. Chaucer is a master of gentle satire. The prioress is polite and fashionable. The pardoner sells relics for money. But the parson is a poor man who does what he teaches. That is the lesson of James 1:22, be doers of the word, and not hearers only.\n\nYour task is to explain a frame narrative, describe two pilgrims, and tell how the parson shows integrity. Take the four question check. Let your life match your words. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Chaucer and the Canterbury Tales$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Everyman and the Medieval Mind$j$, $j${"readings": [{"title": "Matthew 6 (King James Version)", "url": "/portal/bible/Matthew/6"}], "body": "In the Middle Ages most people could not read, so stories were taught through plays, sermons and pictures in stained glass. Morality plays were dramas that taught lessons about how to live. Everyman, written in the late 1400s, is the most famous.\n\nAn allegory is a story in which characters, events and settings stand for ideas, so that the story has a second meaning. In Everyman, God sends Death to summon Everyman, a figure who stands for every human being. Everyman is afraid and asks his friends to go with him. Fellowship, Kindred and Goods all refuse. Only Good Deeds is willing to go with him, though she is weak because Everyman has neglected her. With the help of Knowledge and Confession, Good Deeds grows strong, and Everyman makes peace with God.\n\nThe play's lesson is that earthly friends and riches cannot follow us beyond death, and that faith should be shown in action. Compare Jesus's teaching in Matthew 6:19 to 21: lay not up for yourselves treasures upon earth, but lay up for yourselves treasures in heaven, for where your treasure is, there will your heart be also.\n\nWhen you read an allegory, ask what each character stands for and how the plot shows the lesson.\n\nYour task: (1) Define allegory. (2) List what four characters in Everyman stand for. (3) Explain the lesson about wealth and good deeds, and connect it to Matthew 6:19 to 21.\n\nFlorida standards: ELA.12.R.1.2, ELA.12.R.1.4, ELA.12.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.2, ELA.12.R.1.4, ELA.12.R.3.1", "script": "Welcome back. Listen, in the Middle Ages most people could not read, so the church and the town taught through plays, sermons and pictures in stained glass. One famous play from the late 1400s is called Everyman.\n\nNow watch this. Everyman is an allegory. An allegory is a story where the characters stand for ideas, so there is a second meaning under the surface. In the play, God sends Death to summon Everyman, and Everyman stands for every one of us.\n\nEveryman is afraid. He begs his friends to go with him. Fellowship says no. Kindred says no. Goods, his riches, says no. Only one is willing to go, and her name is Good Deeds. But she is weak, because Everyman has ignored her for years. With help from Knowledge and Confession, she grows strong, and Everyman is ready.\n\nLook at the lesson. Friends and wealth cannot follow us beyond this life, but what we do for God and for others does. Jesus taught the same thing in Matthew 6, lay up for yourselves treasures in heaven.\n\nWhen you read an allegory, ask what each character stands for. Your task is to define allegory, list four characters and what they mean, and explain the lesson. Take the four question check. Build something that lasts. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Everyman and the Medieval Mind$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 How English Changed: Old, Middle and Modern$j$, $j${"readings": [{"title": "Genesis 11 (King James Version)", "url": "/portal/bible/Genesis/11"}], "body": "The English you speak has a long history. Old English, spoken from about the year 450 to 1100, was a Germanic language brought by Angles, Saxons and Jutes. It looks foreign to us. In 1066 William of Normandy conquered England, and French became the language of the court and law. The result was Middle English, spoken from about 1100 to 1500, a blend of English and French. Early Modern English, used by Shakespeare and the King James Bible, began around 1500, helped by the printing press, which William Caxton introduced to England in 1476.\n\nYou can see the history in words. Farm animals kept their English names, such as cow, pig and sheep, while the meat on the table took French names: beef, pork and mutton. The English words were used by the working people and the French words by the nobles who ate the meat.\n\nMany English words come from Latin and Greek roots. The root bene means good, as in benefit and benediction. The root dict means speak, as in dictate and verdict. Learning roots lets you decode hard words, a skill that will help you on college entrance exams.\n\nYour task: (1) Name the three main stages of English with approximate dates. (2) Explain the cow and beef example. (3) Use two roots to break down two words and give their meanings.\n\nFlorida standards: ELA.12.V.1.2, ELA.12.V.1.1, ELA.12.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.V.1.2, ELA.12.V.1.1, ELA.12.R.3.1", "script": "Now let's look at the language itself. Listen, the English you speak every day has a long and surprising history, and understanding it will make you a stronger reader and writer.\n\nOld English was spoken from about the year 450 to 1100. It came with the Angles, Saxons and Jutes, and to our eyes it looks foreign. Then in 1066, William of Normandy conquered England, and French became the language of the court and the law. The blend became Middle English, the language of Chaucer. Around 1500 we reach Early Modern English, the language of Shakespeare and the King James Bible, helped by the printing press that William Caxton brought to England in 1476.\n\nNow watch this. Look at what is on the farm and what is on the table. The animals kept their English names, cow, pig and sheep. But the meat took French names, beef, pork and mutton. The working people raised the animals, and the nobles ate the meat. History is hiding in our vocabulary.\n\nRoots help too. Bene means good, in benefit and benediction. Dict means speak, in dictate and verdict.\n\nYour task is to name the three stages of English, explain the cow and beef example, and break down two words. Take the four question check. Words carry history. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 How English Changed: Old, Middle and Modern$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Beginnings, Old English and Medieval Voices$j$, $j${"prompt": "Write a report of at least 250 words on early British literature. Use complete sentences and label each part. Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nPart 1: Choose Beowulf, The Canterbury Tales or Everyman. Summarize it and name its form (epic, frame narrative or allegory).\nPart 2: Name and explain two literary features from the work you chose, with an example of each.\nPart 3: Tell what the work shows about the values of its time, such as courage, honesty, faith or good deeds.\nPart 4: Compare one idea in the work with a passage from Scripture, such as 1 Samuel 17, James 1:22 or Matthew 6:19 to 21.\nPart 5: Explain how Old, Middle and Modern English differ, and give one example word from French, Latin or Greek roots.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Beginnings, Old English and Medieval Voices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Heroes, Pilgrims and Good Deeds$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes what makes a person a hero in your opinion, (2) compares the Anglo Saxon idea of a hero with a hero from Scripture, (3) tells which medieval work in this unit you found most interesting and why, and (4) connects your answer to Micah 6:8, which says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God? Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think stories from long ago still matter today? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Heroes, Pilgrims and Good Deeds$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Beowulf and the Anglo Saxon Hero$j$, $j${"questions": [{"q": "Beowulf is best described as:", "options": ["A modern novel", "A play by Shakespeare", "An epic poem in Old English", "A newspaper article"]}, {"q": "A kenning is:", "options": ["A pause in the middle of a line", "A compound phrase that names a thing indirectly, like whale road", "A rhyming couplet", "A repeated chorus"]}, {"q": "Beowulf's three great battles are against:", "options": ["Three kings", "Three dragons", "Grendel, Grendel's mother and a dragon", "Grendel only"]}, {"q": "A caesura is:", "options": ["A pause in the middle of a line of poetry", "A long speech", "The title of a poem", "A type of rhyme"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Beowulf and the Anglo Saxon Hero$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,2,0}'::int[], array[$j$Beowulf is an Old English epic poem.$j$,$j$A kenning is a picture name made from two words.$j$,$j$He defeats Grendel, then his mother, then faces a dragon as an old king.$j$,$j$A caesura is a pause within a line.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Beowulf and the Anglo Saxon Hero$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Chaucer and the Canterbury Tales$j$, $j${"questions": [{"q": "The Canterbury Tales is told by:", "options": ["Students in a school", "Pilgrims traveling to Canterbury", "Kings in a castle", "Soldiers at war"]}, {"q": "Chaucer wrote in:", "options": ["Old English", "Latin only", "Modern American English", "Middle English"]}, {"q": "A frame narrative is:", "options": ["A speech with no ending", "A poem about a picture", "A story that holds other stories inside it", "A list of facts"]}, {"q": "In the General Prologue, the parson is shown as:", "options": ["A proud knight", "A humble man who practices what he preaches", "A greedy seller of relics", "A lazy traveler"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Chaucer and the Canterbury Tales$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,1}'::int[], array[$j$Pilgrims tell stories on the road to Canterbury.$j$,$j$He wrote in Middle English in the late 1300s.$j$,$j$The pilgrimage is the frame for all the tales.$j$,$j$The parson is the model of integrity.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Chaucer and the Canterbury Tales$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Everyman and the Medieval Mind$j$, $j${"questions": [{"q": "An allegory is:", "options": ["A list of rules", "A story whose characters and events stand for ideas", "A poem about nature", "A speech to a crowd"]}, {"q": "In Everyman, who is willing to go with him to the end?", "options": ["Goods", "Kindred", "Fellowship", "Good Deeds"]}, {"q": "Everyman stands for:", "options": ["A monster", "A wealthy merchant only", "One king", "Every human being"]}, {"q": "The lesson of Everyman is that:", "options": ["Friends can always follow us", "Good deeds matter more than riches at death", "Wealth lasts forever", "Fear is the best guide"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Everyman and the Medieval Mind$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,1}'::int[], array[$j$An allegory has a second, symbolic meaning.$j$,$j$Only Good Deeds goes with Everyman.$j$,$j$The name signals that he represents everyone.$j$,$j$Earthly wealth and friends cannot follow beyond death.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Everyman and the Medieval Mind$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: How English Changed: Old, Middle and Modern$j$, $j${"questions": [{"q": "The Norman Conquest of England happened in:", "options": ["1776", "1492", "1066", "1215"]}, {"q": "Which language became the language of the English court after 1066?", "options": ["French", "Greek", "German", "Spanish"]}, {"q": "The words beef, pork and mutton come from:", "options": ["French", "Hebrew", "Old English", "Chinese"]}, {"q": "The root bene means:", "options": ["Speak", "Carry", "Good", "Write"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: How English Changed: Old, Middle and Modern$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,2}'::int[], array[$j$William of Normandy won in 1066.$j$,$j$Norman French influenced court and law.$j$,$j$The nobles who ate the meat used French words.$j$,$j$Bene means good, as in benefit.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: How English Changed: Old, Middle and Modern$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Beginnings, Old English and Medieval Voices$j$, $j${"questions": [{"q": "Beowulf was composed in:", "options": ["Modern English", "Middle English", "Old English", "French"]}, {"q": "Alliteration is:", "options": ["Repetition of beginning sounds", "A type of rhyme at line ends", "A story with symbols", "A pause in a line"]}, {"q": "Chaucer's pilgrims were traveling to:", "options": ["Rome", "Canterbury", "Paris", "London"]}, {"q": "A frame narrative is:", "options": ["A poem about a painting", "A story with no characters", "A story that contains other stories", "A list"]}, {"q": "In Everyman, Good Deeds stands for:", "options": ["The actions a person does for God and others", "Fear", "Money", "Friends"]}, {"q": "Early Modern English was helped by:", "options": ["Television", "The printing press", "The typewriter", "The telephone"]}, {"q": "The word cow comes from Old English, and beef comes from:", "options": ["Greek only", "Latin only", "French", "Arabic"]}, {"q": "The root dict means:", "options": ["Light", "Speak", "Carry", "Good"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Beginnings, Old English and Medieval Voices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,2,0,1,2,1}'::int[], array[$j$It is an Old English poem.$j$,$j$Alliteration repeats initial sounds.$j$,$j$They traveled to the shrine at Canterbury.$j$,$j$The pilgrimage frames the tales.$j$,$j$Good Deeds represents works of faith and love.$j$,$j$Caxton brought the press to England in 1476.$j$,$j$The nobles used French words for meat.$j$,$j$Dict means speak, as in dictate.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Beginnings, Old English and Medieval Voices$j$ on conflict (item_id) do nothing;
